function tau_M_lpf = mfun_ovhz_torque_filter(tau_M, p)
%MFUN_OVHZ_TORQUE_FILTER Block tau_M_lpf of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the Simulink model, which adds its folder to the MATLAB
%   path. The parameters are the fields of the struct p (from the mask, [] as NaN). The
%   state is in persistent variables, of which each MATLAB Function block has its own
%   copy. The inputs without direct feedthrough come through unit delays, so the update
%   of the state with them is done at the next call.
persistent self pending
if isempty(self)
    % Low-pass-filtered torque estimate
    self = 0;
    pending = false;
end
% Update of the previous sampling period with its inputs (the inputs
% tau_M through unit delays)
if pending
    self = self + p.T_s*p.alpha_f*(tau_M - self);
end
pending = true;
tau_M_lpf = self;
end
